const conversations={
 groceries:{title:'The plan becomes a shopping list.',copy:'Keep the foods in your existing plan. Leave what’s already at home off the shopping list.',points:['Your own plan','Your home-stock updates','You place the order'],messages:[['mine','My food plan has eggs, curd and spinach. I already have curd.'],['theirs','Which of these do you need to buy?'],['mine','Eggs and spinach.'],['theirs','What’s left to buy: eggs and spinach.']]},
 workouts:{title:'Keep the plan. Add the update.',copy:'Keep an existing workout or physio plan, then record what you did. Correct the date without adding another session.',points:['Existing plans kept separately','Reported updates only','Ordinary-word corrections'],messages:[['mine','My physio plan is Mondays at 6pm.'],['theirs','Kept your existing physio schedule.'],['mine','I did today’s session.'],['theirs','Recorded your physio session.']]},
 questions:{title:'The question, ready when you need it.',copy:'Keep the question while it’s on your mind. Ask for your own words before the appointment.',points:['Your questions','Your reported notes','No medical advice'],messages:[['mine','Keep a question for my doctor: what should I discuss about my sleep?'],['theirs','Kept your question.'],['mine','What was my question for the doctor?'],['theirs','“What should I discuss about my sleep?”']]}
};
const tick='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="m5 12 4 4 10-10"/></svg>';
function choose(id){const info=conversations[id];document.querySelectorAll('[role=tab]').forEach(tab=>{const active=tab.dataset.example===id;tab.setAttribute('aria-selected',String(active));tab.tabIndex=active?0:-1;});document.querySelector('#example-panel').setAttribute('aria-labelledby','tab-'+id);document.querySelector('#example-title').textContent=info.title;document.querySelector('#example-copy').textContent=info.copy;document.querySelector('#example-points').innerHTML=info.points.map(x=>'<li>'+tick+x+'</li>').join('');const chat=document.querySelector('#chat-messages');chat.replaceChildren(...info.messages.map(([kind,text])=>{const bubble=document.createElement('p');bubble.className='bubble '+kind;bubble.textContent=text;return bubble;}));}
const tabs=[...document.querySelectorAll('[role=tab]')];tabs.forEach((tab,index)=>{tab.addEventListener('click',()=>choose(tab.dataset.example));tab.addEventListener('keydown',event=>{let next;if(event.key==='ArrowRight')next=(index+1)%tabs.length;else if(event.key==='ArrowLeft')next=(index+tabs.length-1)%tabs.length;else if(event.key==='Home')next=0;else if(event.key==='End')next=tabs.length-1;else return;event.preventDefault();choose(tabs[next].dataset.example);tabs[next].focus();});});
choose('groceries');
